CREATE FUNCTION public.add_product(b uuid,n text,s text,c text,cost_value numeric,price_value numeric,stock_value numeric,min_value numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou acesso negado'; END IF; INSERT INTO public.products(business_id,name,sku,category,cost,price,stock,min_stock) VALUES(b,n,s,c,cost_value,price_value,stock_value,min_value) RETURNING id INTO p; IF stock_value>0 THEN INSERT INTO public.inventory_movements(business_id,product_id,quantity,kind) VALUES(b,p,stock_value,'opening'); END IF; RETURN p; END $$;
CREATE FUNCTION public.add_contact(b uuid,kind text,n text,ph text,em text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou acesso negado'; END IF; IF kind='customer' THEN INSERT INTO public.customers(business_id,name,phone,email) VALUES(b,n,ph,em) RETURNING id INTO p; ELSIF kind='supplier' THEN INSERT INTO public.suppliers(business_id,name,phone,email) VALUES(b,n,ph,em) RETURNING id INTO p; ELSE RAISE EXCEPTION 'Tipo inválido'; END IF; RETURN p; END $$;
CREATE FUNCTION public.record_expense(b uuid,cat text,val numeric,d date,n text,r text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou acesso negado'; END IF; IF r IS NOT NULL AND split_part(r,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'Comprovativo inválido'; END IF; INSERT INTO public.expenses(business_id,category,amount,expense_date,notes,receipt_path) VALUES(b,cat,val,d,n,r) RETURNING id INTO p; RETURN p; END $$;
CREATE FUNCTION public.record_sale(b uuid,customer uuid,items jsonb,discount_value numeric,paid_value numeric,method text,due date,req uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sale uuid; item jsonb; prod public.products; q numeric; total_value numeric:=0; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou accès negado'; END IF; SELECT id INTO sale FROM public.sales WHERE request_id=req AND business_id=b; IF sale IS NOT NULL THEN RETURN sale; END IF; IF jsonb_array_length(items)<1 OR jsonb_array_length(items)>100 OR discount_value<0 THEN RAISE EXCEPTION 'Venda inválida'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(items) ORDER BY value->>'product_id' LOOP q:=(item->>'quantity')::numeric; SELECT * INTO prod FROM public.products WHERE id=(item->>'product_id')::uuid AND business_id=b AND active FOR UPDATE; IF NOT FOUND OR q<=0 OR prod.stock<q THEN RAISE EXCEPTION 'Produto indisponível ou stock insuficiente'; END IF; total_value:=total_value+round(q*prod.price,2); END LOOP; total_value:=total_value-discount_value; IF total_value<0 OR paid_value<0 OR paid_value>total_value OR (paid_value<total_value AND (customer IS NULL OR due IS NULL)) THEN RAISE EXCEPTION 'Pagamento ou desconto inválido'; END IF; INSERT INTO public.sales(business_id,customer_id,total,discount,paid,payment_method,request_id) VALUES(b,customer,total_value,discount_value,paid_value,method,req) RETURNING id INTO sale; FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP q:=(item->>'quantity')::numeric; SELECT * INTO prod FROM public.products WHERE id=(item->>'product_id')::uuid AND business_id=b FOR UPDATE; IF prod.stock<q THEN RAISE EXCEPTION 'Stock insuficiente'; END IF; INSERT INTO public.sale_items(business_id,sale_id,product_id,quantity,unit_price,unit_cost) VALUES(b,sale,prod.id,q,prod.price,prod.cost); UPDATE public.products SET stock=stock-q WHERE id=prod.id; INSERT INTO public.inventory_movements(business_id,product_id,quantity,kind,notes) VALUES(b,prod.id,-q,'sale',sale::text); END LOOP; IF paid_value<total_value THEN INSERT INTO public.receivables(business_id,customer_id,sale_id,amount,due_date) VALUES(b,customer,sale,total_value-paid_value,due); END IF; INSERT INTO public.audit_logs(business_id,actor_id,event,record_id) VALUES(b,auth.uid(),'sale.created',sale); RETURN sale; END $$;
CREATE FUNCTION public.receive_debt(b uuid,r uuid,val numeric,m text,req uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE debt public.receivables; p uuid; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou acesso negado'; END IF; SELECT * INTO debt FROM public.receivables WHERE id=r AND business_id=b FOR UPDATE; IF NOT FOUND OR debt.cancelled OR val<=0 OR val>debt.amount-debt.paid THEN RAISE EXCEPTION 'Valor inválido'; END IF; SELECT id INTO p FROM public.payments WHERE request_id=req AND business_id=b; IF p IS NOT NULL THEN RETURN p; END IF; INSERT INTO public.payments(business_id,receivable_id,amount,method,request_id) VALUES(b,r,val,m,req) RETURNING id INTO p; UPDATE public.receivables SET paid=paid+val WHERE id=r; INSERT INTO public.audit_logs(business_id,actor_id,event,record_id,details) VALUES(b,auth.uid(),'debt.payment',r,jsonb_build_object('amount',val)); RETURN p; END $$;
CREATE FUNCTION public.record_purchase(b uuid,s uuid,p uuid,q numeric,c numeric,paid_value numeric,req uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE purchase uuid; BEGIN IF NOT public.business_active(b) THEN RAISE EXCEPTION 'Subscrição expirada ou acesso negado'; END IF; SELECT id INTO purchase FROM public.purchases WHERE request_id=req AND business_id=b; IF purchase IS NOT NULL THEN RETURN purchase; END IF; PERFORM 1 FROM public.products WHERE id=p AND business_id=b FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Produto inválido'; END IF; INSERT INTO public.purchases(business_id,supplier_id,product_id,quantity,unit_cost,paid,request_id) VALUES(b,s,p,q,c,paid_value,req) RETURNING id INTO purchase; UPDATE public.products SET stock=stock+q,cost=c WHERE id=p AND business_id=b; INSERT INTO public.inventory_movements(business_id,product_id,quantity,kind,notes) VALUES(b,p,q,'purchase',purchase::text); RETURN purchase; END $$;
CREATE FUNCTION public.reverse_sale(b uuid,s uuid,reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sale public.sales; item public.sale_items; BEGIN IF NOT public.business_active(b) OR length(trim(reason))<5 THEN RAISE EXCEPTION 'Acesso ou motivo inválido'; END IF; SELECT * INTO sale FROM public.sales WHERE id=s AND business_id=b FOR UPDATE; IF NOT FOUND OR sale.status<>'confirmed' THEN RAISE EXCEPTION 'Venda inválida ou já estornada'; END IF; IF EXISTS(SELECT 1 FROM public.receivables WHERE sale_id=s AND paid>0) THEN RAISE EXCEPTION 'Venda com recebimentos posteriores: requer conciliação antes do estorno'; END IF; FOR item IN SELECT * FROM public.sale_items WHERE sale_id=s ORDER BY product_id LOOP UPDATE public.products SET stock=stock+item.quantity WHERE id=item.product_id AND business_id=b; INSERT INTO public.inventory_movements(business_id,product_id,quantity,kind,notes) VALUES(b,item.product_id,item.quantity,'reversal',reason); END LOOP; UPDATE public.sales SET status='reversed',reversal_reason=reason WHERE id=s; UPDATE public.receivables SET cancelled=true WHERE sale_id=s; INSERT INTO public.audit_logs(business_id,actor_id,event,record_id,details) VALUES(b,auth.uid(),'sale.reversed',s,jsonb_build_object('reason',reason)); END $$;
CREATE FUNCTION public.request_subscription(b uuid,p text,ref text,r text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.owns_business(b) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.plans WHERE id=p AND enabled) OR NOT EXISTS(SELECT 1 FROM public.payment_settings WHERE bank_name<>'' AND account_holder<>'' AND iban<>'') THEN RAISE EXCEPTION 'Plano ou dados bancários indisponíveis'; END IF; IF r IS NOT NULL AND split_part(r,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'Comprovativo inválido'; END IF; INSERT INTO public.payment_requests(business_id,plan_id,reference,receipt_path) VALUES(b,p,upper(trim(ref)),r) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.review_payment(r uuid,approve boolean,note text,independently_verified boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE payment public.payment_requests; plan public.plans; expiry timestamptz; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO payment FROM public.payment_requests WHERE id=r FOR UPDATE; IF NOT FOUND OR payment.status<>'pending' THEN RAISE EXCEPTION 'Pedido já revisto ou inválido'; END IF; IF public.owns_business(payment.business_id) THEN RAISE EXCEPTION 'Não podes rever o teu próprio pagamento'; END IF; IF length(trim(note))<5 OR (approve AND NOT independently_verified) THEN RAISE EXCEPTION 'Verificação independente e nota obrigatórias'; END IF; PERFORM 1 FROM public.businesses WHERE id=payment.business_id FOR UPDATE; IF approve THEN SELECT * INTO plan FROM public.plans WHERE id=payment.plan_id; SELECT greatest(now(),coalesce(max(expires_at),now())) INTO expiry FROM public.subscriptions WHERE business_id=payment.business_id; INSERT INTO public.subscriptions(business_id,plan_id,starts_at,expires_at) VALUES(payment.business_id,plan.id,now(),expiry+make_interval(days=>plan.duration_days)); END IF; UPDATE public.payment_requests SET status=CASE WHEN approve THEN 'approved' ELSE 'rejected' END,reviewed_by=auth.uid(),reviewed_at=now(),review_note=note WHERE id=r; INSERT INTO public.audit_logs(business_id,actor_id,event,record_id,details) VALUES(payment.business_id,auth.uid(),CASE WHEN approve THEN 'payment.approved' ELSE 'payment.rejected' END,r,jsonb_build_object('note',note,'independently_verified',independently_verified)); END $$;
CREATE FUNCTION public.configure_bank(bank text,holder text,account text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF; INSERT INTO public.payment_settings(id,bank_name,account_holder,iban) VALUES(true,left(bank,100),left(holder,150),left(account,100)) ON CONFLICT(id) DO UPDATE SET bank_name=excluded.bank_name,account_holder=excluded.account_holder,iban=excluded.iban,updated_at=now(); INSERT INTO public.audit_logs(actor_id,event) VALUES(auth.uid(),'bank.updated'); END $$;
DO $$ DECLARE fn record; BEGIN FOR fn IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('add_product','add_contact','record_expense','record_sale','receive_debt','record_purchase','reverse_sale','request_subscription','review_payment','configure_bank') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',fn.signature); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',fn.signature); END LOOP; END $$;